declare_lint ! { #[doc = " The `clashing_extern_declarations` lint detects when an `extern fn`"] #[doc = " has been declared with the same name but different types."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " mod m {"] #[doc = "     unsafe extern \"C\" {"] #[doc = "         fn foo();"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " unsafe extern \"C\" {"] #[doc = "     fn foo(_: u32);"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Because two symbols of the same name cannot be resolved to two"] #[doc = " different functions at link time, and one function cannot possibly"] #[doc = " have two types, a clashing extern declaration is almost certainly a"] #[doc = " mistake. Check to make sure that the `extern` definitions are correct"] #[doc = " and equivalent, and possibly consider unifying them in one location."] #[doc = ""] #[doc = " This lint does not run between crates because a project may have"] #[doc = " dependencies which both rely on the same extern function, but declare"] #[doc = " it in a different (but valid) way. For example, they may both declare"] #[doc = " an opaque type for one or more of the arguments (which would end up"] #[doc = " distinct types), or use types that are valid conversions in the"] #[doc = " language the `extern fn` is defined in. In these cases, the compiler"] #[doc = " can't say that the clashing declaration is incorrect."] pub CLASHING_EXTERN_DECLARATIONS , Warn , "detects when an extern fn has been declared with the same name but different types" }